import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { connect } from "node:net";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, beforeEach, expect, it } from "vitest";
import { deps, URLError } from "./runtime.js";
import { CloudFixture } from "./testFixture.js";
let fixture;
let servers;
beforeEach(() => {
    fixture = new CloudFixture();
    servers = [];
    for (const name of [
        "https_proxy",
        "HTTPS_PROXY",
        "http_proxy",
        "HTTP_PROXY",
        "no_proxy",
        "NO_PROXY",
    ]) {
        delete process.env[name];
    }
});
afterEach(async () => {
    await Promise.all(servers.map((server) => new Promise((resolve) => {
        server.closeAllConnections();
        server.close(resolve);
    })));
    fixture.dispose();
});
async function listen(server) {
    servers.push(server);
    await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
    return `http://127.0.0.1:${server.address().port}`;
}
function answering(body, seen) {
    return createServer((request, response) => {
        seen.push(`${request.method} ${request.url}`);
        response.end(body);
    });
}
it("sends requests through HTTP_PROXY", async () => {
    const seen = [];
    const target = await listen(answering('{"via": "proxy"}', []));
    const proxy = createServer();
    proxy.on("connect", (request, socket) => {
        seen.push(`${request.method} ${request.url}`);
        const upstream = connect(Number(new URL(target).port), "127.0.0.1", () => {
            socket.write("HTTP/1.1 200 Connection Established\r\n\r\n");
            upstream.pipe(socket);
            socket.pipe(upstream);
        });
    });
    process.env.HTTP_PROXY = await listen(proxy);
    const body = await deps.urlopen("http://target.test/api/sdk/x", {
        timeout: 10,
    });
    expect(JSON.parse(body.toString())).toEqual({ via: "proxy" });
    expect(seen).toEqual(["CONNECT target.test:80"]);
});
it("tunnels https requests through HTTPS_PROXY", async () => {
    const seen = [];
    const proxy = createServer();
    proxy.on("connect", (request, socket) => {
        seen.push(`${request.method} ${request.url}`);
        socket.end("HTTP/1.1 403 Forbidden\r\n\r\n");
    });
    process.env.HTTPS_PROXY = await listen(proxy);
    await expect(deps.urlopen("https://api.github.com/repos/acme/app", { timeout: 10 })).rejects.toBeInstanceOf(URLError);
    expect(seen).toEqual(["CONNECT api.github.com:443"]);
});
it("goes direct to hosts in NO_PROXY", async () => {
    const proxied = [];
    const direct = [];
    process.env.HTTP_PROXY = await listen(answering("proxy", proxied));
    const target = await listen(answering("direct", direct));
    process.env.NO_PROXY = "127.0.0.1";
    const body = await deps.urlopen(`${target}/x`, { timeout: 10 });
    expect(body.toString()).toBe("direct");
    expect(proxied).toEqual([]);
    expect(direct).toEqual(["GET /x"]);
});
it("goes direct when no proxy is set", async () => {
    const direct = [];
    const target = await listen(answering("direct", direct));
    const body = await deps.urlopen(`${target}/x`, { timeout: 10 });
    expect(body.toString()).toBe("direct");
});
it("the bundled helper the SDKs ship sends GitHub requests through HTTPS_PROXY", async () => {
    const seen = [];
    const proxy = createServer();
    proxy.on("connect", (request, socket) => {
        seen.push(`${request.method} ${request.url}`);
        socket.end("HTTP/1.1 403 Forbidden\r\n\r\n");
    });
    const proxyUrl = await listen(proxy);
    fixture.git("remote", "set-url", "origin", "https://github.com/acme/app.git");
    const bundle = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../../bitfab-typescript-sdk/cloudReplay.mjs");
    const child = spawn(process.execPath, [bundle, ...fixture.argv], {
        cwd: fixture.root,
        env: {
            ...process.env,
            GH_TOKEN: "token",
            HTTPS_PROXY: proxyUrl,
            PATH: path.dirname(process.execPath) + path.delimiter + "/usr/bin:/bin",
            BITFAB_REPLAY_COMMAND: JSON.stringify([process.execPath, "registry.mjs"]),
            BITFAB_REPLAY_ARGUMENTS_CHECKED: "1",
        },
    });
    let stderr = "";
    child.stderr.on("data", (chunk) => {
        stderr += chunk;
    });
    const code = await new Promise((resolve) => child.on("close", resolve));
    expect(code, stderr).toBe(1);
    expect(seen).toEqual(["CONNECT api.github.com:443"]);
});
it("names why a host could not be reached", async () => {
    const closed = await listen(answering("", []));
    await new Promise((resolve) => servers.pop()?.close(resolve));
    const error = await deps
        .urlopen(`${closed}/x`, { timeout: 10 })
        .catch((caught) => caught);
    expect(error).toBeInstanceOf(URLError);
    expect(error.reason).toMatch(/ECONNREFUSED/);
});
it("keeps reading a slow body that keeps arriving past the timeout", async () => {
    const server = createServer((_request, response) => {
        let sent = 0;
        const tick = setInterval(() => {
            response.write("x");
            sent += 1;
            if (sent === 6) {
                clearInterval(tick);
                response.end();
            }
        }, 400);
    });
    const target = await listen(server);
    const body = await deps.urlopen(`${target}/log`, { timeout: 1 });
    expect(body.toString()).toBe("xxxxxx");
});
it("gives up when a body stops arriving for the timeout", async () => {
    const server = createServer((_request, response) => {
        response.write("x");
    });
    const target = await listen(server);
    const error = await deps
        .urlopen(`${target}/log`, { timeout: 1 })
        .catch((caught) => caught);
    expect(error).toBeInstanceOf(URLError);
    expect(error.reason).toMatch(/timed out after 1 seconds/);
});
